from pathlib import Path
import json,hashlib
B=Path(__file__).parent
sq=json.loads((B/'seed-v1/questions.json').read_text()); sk=json.loads((B/'seed-v1/answer-key.json').read_text())
qs=list(sq['questions']); keys=list(sk['answers']); novelty=[]
def add(q,a,refs,new):
 i=f'Q{len(qs)+1:02}'; qs.append({'id':i,'question':q}); keys.append({'id':i,'answer':a,'source_refs':refs}); novelty.append({'id':i,'new_coverage':new,'source_refs':refs})
add('What makes two lands adjacent, including across boards? Are all outside-edge lands Coastal, is Ocean normally a land, and can a land be adjacent to itself or within Range 1 of itself?', 'Adjacency is sharing a border or corner, including across boards. Coastal means touching printed Ocean, not cliff edges; other lands are Inland. Ocean is not normally a land/in play. A land is not adjacent to itself but is Range 0 of itself and hence within Range 1.', ['CORE pp.13,31-32','FAQ Core: is-a-land-adjacent-to-or-within-range-of-itself'], 'Geographic corner/cross-board, cliff/coast and adjacency-vs-range distinctions.')
add('How is a Spirit’s starting hand obtained, where is its setup Presence placed, what if multiple legal setup choices or two placement instructions name the same land, and is its later play confined to that board?', 'Take its four Unique cards as starting hand, follow back-panel setup on a different starting board per Spirit, choose among equally legal options, and allow multiple instructions to place in the same land. Later Presence and Powers may use any board.', ['CORE p.6','FAQ Setup: Spirit-with-multiple-ways-to-set-up; two-setup-instructions-placing-presence-in-the-same-land'], 'Starting hand, setup choice/overlap, freedom beyond starting board.')
add('Does one Presence each from two Spirits form a Sacred Site? Does four Presence from one Spirit count as two sites, and what does “your land” mean?', 'No, ordinarily one Spirit needs at least two own disks. Four of that Spirit’s disks in one land still make only one site. Your land is a land containing your Presence.', ['CORE p.13','FAQ Core: .9v5ka9f'], 'Ownership and non-multiplication of Sacred Sites.')
add('A Growth option includes an impossible instruction and an explicit cost. Can it be selected, can possible instructions be skipped, and may one Spirit wait for another’s Growth result before choosing?', 'May select despite an impossible non-cost instruction, doing all possible instructions in any order and skipping impossible parts. Explicit cost must be paid in full. May wait for another Spirit’s Growth result; each obeys own Growth/Energy/play order and all finish Spirit Phase before any Fast resolution.', ['CORE p.8','FAQ Core: .3y28aul; .7w4g7z1'], 'Impossible Growth versus mandatory cost, asynchronous Spirit ordering.')
add('What cards does ordinary Reclaim return, and when and how often can a newly uncovered Reclaim One space be used?', 'Ordinary Reclaim returns all personal-discard cards to hand, not currently played or forgotten cards. Reclaim One returns one personal-discard card at any time during Spirit Phase once per phase, including the turn it is uncovered.', ['CORE pp.14,31'], 'Reclaim destinations and immediate once-per-phase track ability.')
add('When a track Element is revealed after Growth, when does it become usable? When may an Any track Element be chosen and changed, and what if an in-play card is Forgotten?', 'Track Element is usable immediately whenever revealed and continuously while uncovered. Any may be selected at any time in the turn but cannot change once chosen until next turn. Forgetting an in-play card immediately removes its Elements.', ['CORE pp.14,16,18','FAQ Core: .7w4g8rf; .7w4g8p4'], 'Mid-turn Elements, delayed Any choice versus fixed choice.')
add('A Power’s earlier instruction uncovers an Element needed for a later threshold. Can that later threshold apply? What if Elements are lost instead, and can earlier resolved effects be revised?', 'Yes, check Elements at the later threshold. Lost Elements can prevent later thresholds. Completed effects cannot be revised retroactively; Speed/Range/targeting modifications must be checked when selecting/using those attributes, and or-branch choice precedes branch resolution.', ['FAQ Core: .9v5kcmx; .bu6od0c'], 'Within-Power dynamic thresholds and non-retroactivity.')
add('Must a land at Range 0 contain your Presence? Can a numeric Range boost waive a Sacred Site origin, a target-terrain restriction or the text “one of your lands”?', 'Range 0 ordinarily means a land containing your Presence. A boost only extends numeric Range; it does not waive Sacred Site/source, terrain/contents target restrictions or the requirement that a land be one of yours.', ['CORE pp.16,32','FAQ Core: .3y28aqg; .7w4g8nq'], 'Source/target restrictions survive range boosts.')
add('May a legally targeted Power count as used if its instructions accomplish nothing? Does foregoing its text count as targeting it? Can an innate with only its own Speed/Range modification available be used?', 'May target and use a legal Power even if nothing actually changes, provided it has an instruction with potential to affect game state and attempts its text. Foregoing the text is not using/targeting it. Merely modifying its own Speed/Range does not qualify.', ['FAQ Core: .7w4gebo; .7w4gee1; can-an-innate-power-that-only-changes-speed-or-range-be-targeted'], 'Attempted no-effect use versus foregoing versus self-modifier-only innate.')
add('A card adds a Town in Slow and says Invaders skip Build this turn. What remains next turn? At Time Passes where do played cards go, what happens to damaged survivors and reminder markers, and do track Elements vanish?', 'Added Town remains as a board change. Build skip expires at Time Passes. Played cards go to personal discard, all surviving Invader/Dahan Damage clears, card Elements and temporary effects clear, reminder markers removed. Track Elements remain while uncovered.', ['CORE pp.10,16-17'], 'Persistent board changes versus temporary effects and full cleanup.')
add('Do damaged Invaders and Dahan deal less Damage? If Defend 1 and Defend 2 both affect a land with total Invader Damage 4, what Damage reaches the land and Dahan?', 'Damaged pieces deal normal Damage. Defend adds to 3, reducing 4 to 1 separately to land and Dahan, so no Blight and one Dahan takes 1 Damage if present.', ['CORE pp.9,18','FAQ Core: .9v5kc4h'], 'Outgoing Damage independent of marked Damage; additive separate Defend.')
add('If a Town is replaced by an Explorer while retaining 1 Damage, does the replacement itself cause Fear, does the Explorer survive, and why? Can reduced Health destroy a piece without new Damage?', 'Replacement itself causes no Fear. Retained 1 Damage meets Explorer Health 1, so it is destroyed, giving no Fear for an Explorer. More generally, a piece is destroyed immediately once existing Damage meets its reduced/new Health, even without new Damage.', ['CORE pp.15,18','FAQ Core: .bu6oczl'], 'Health-reduction/replacement consequence (specific boundary of Q18).')
add('Do Dahan automatically attack when a Spirit damages or Pushing Invaders into their land, and can a Power’s unqualified Damage hit Dahan? Are Dahan and Invaders limited by the physical supply?', 'No automatic Dahan attack except Ravage counterattack or explicit Power instruction. Unqualified Power Damage is to Invaders; Dahan require explicit harmful instructions. Dahan and Invaders are unlimited; use substitutes when pieces run out.', ['CORE pp.15-16,18'], 'Dahan attack trigger and supply exhaustion not eliminating pieces.')
add('Do increased Range and a large number of pieces let a single ordinary Power distribute its effects across multiple target lands? What does Push up to 3 Explorer/Town allow in terms of total pieces?', 'No; all ordinary effects remain in one target land, except explicit instructions such as Push destinations. Slash means either/both types within a combined limit: up to three pieces total, not three of each.', ['CORE pp.16-17,32','FAQ Core: .9v5kavt'], 'One-target rule and slash union combined allowance.')
add('If Gather 3 or Push 3 lacks “up to,” may the player move only one when three legal pieces are available? What if only two are available? Can unrestricted Move leave a piece in its current land?', 'Must move three if possible, otherwise as many as possible (two). Unrestricted Move can choose the current land and counts as movement; Gather/Push cannot because they require an adjacent land.', ['CORE pp.17,19','FAQ Core: .7w4g8of; .9v5kfr0'], 'Mandatory amount versus up-to and generic movement versus adjacency.')
add('What is the difference between a Growth Move Presence arrow and Add Presence using an island disk? Can the latter pick up a disk outside the shown Range of the destination?', 'Move measures from that disk’s present land and moves up to the arrow’s distance. Add/reposition first picks a legal destination measured from any existing Presence, then may take any own island disk, even one far from that destination. It remains adding, not a Move instruction.', ['CORE p.14','FAQ Core: .7w4g8oq; .bu6od08'], 'Different origin/disk selection semantics of Move and reposition.')
add('May a newly gained Growth Power be played in the same Spirit Phase? Does a Power gained in Fast automatically enter play or resolve immediately, and is there a hand-size or hand-secrecy limit?', 'A Growth-gained card enters hand and may be played in the later play/pay step. A Fast-gained card merely enters hand unless explicitly permitted to play it; even explicit play does not immediately resolve unless stated. No hand-size limit; hands can be shown.', ['CORE pp.8,18','FAQ Core: .9v5kcmw; timing-of-resolving-a-power-played-mid-turn'], 'Gain versus play versus resolve, same-turn Growth gain.')
add('An effect explicitly allows playing a card in Fast after the Spirit used all normal Card Plays. Is this legal and when are its Elements/effects available?', 'Yes, effect-granted plays are additional to the normal Spirit-phase track limit. Follow payment instructions, gain Elements immediately, and use effects in its speed phase when no other action is resolving, unless explicitly instructed otherwise.', ['FAQ Core: .bu6ocb5; timing-of-resolving-a-power-played-mid-turn'], 'Extra plays exceed track without automatic nested resolution.')
add('If Entwined Power gifts a Major Power, must the recipient Forget? If a Spirit instead gains two Majors, can a single Forget cover both? Is an ordinary forgotten Unique reclaimable?', 'Gifting/transferring is not Gain and requires no Forget. Each Major gained needs its own separate Forget, unless explicitly exempted, so one card cannot cover both. A forgotten Unique is under panel and cannot be retrieved by ordinary Reclaim/gain.', ['CORE p.18','FAQ Core: .7w4g8pe; .7w4gee7; .9v5kc40'], 'Transfer versus Gain and non-sharing Forget requirements.')
add('When a Fast Gift of Strength or Powerstorm grants a Repeat, must the card be chosen immediately? Can the chosen card be Slow, can it be an innate, and do you gain its printed Elements again?', 'Choose eligible Power Card when actually repeating, not necessarily at grant time. Slow cards can be repeated in Slow; these two effects specify cards and cannot repeat Innates. Printed card Elements are not granted again; explicit Elements in the repeated text are granted again.', ['CORE p.19','FAQ Core: timing-of-choosing-powers-for-once-this-turn-repeats; .7w4g8op; .3y28aex; .9v5ka9b'], 'Delayed Repeat choice and card/innate limitation.')
add('If a Power’s Range was increased and it was made Fast, what happens on Repeat? If Elements enabling a non-Range threshold have been lost, does the Repeat automatically retain that threshold?', 'Range/speed modifications carry over, so Repeat retains extended Range and Fast speed. Thresholds otherwise check current Elements; losing them may mean a previously met threshold no longer applies.', ['CORE p.19','FAQ Core: .9v5kavs; Repeating-internal-range-boosts'], 'Persistent attribute modifications versus rechecked threshold effects.')
add('What happens when Powerstorm itself is Repeated, and can its threshold spend all three Repeat permissions on the same Power Card?', 'Repeat instructions on a repeated Power are ignored, so repeating Powerstorm grants no Repeat permissions; its non-Repeat Energy gain still happens. Its threshold allows up to three different Power Cards, not the same one three times.', ['CORE p.19','FAQ Core: repeating-power-cards-that-grant-repeats; .7w4g8q9'], 'No repeat-permission chains, non-repeat effects survive, distinct cards.')
add('A Power says Repeat this Power in an adjacent land, but that land fails the original Blight target restriction or normal Range. Is it legal, and can the original land be selected?', 'Explicit Repeat location overrides original Range/target restrictions, so the adjacent land can be used despite them. Original land is not adjacent to itself and cannot be selected under this instruction.', ['CORE p.19','FAQ Core: .9v5kfgr; is-a-land-adjacent-to-or-within-range-of-itself'], 'Specified Repeat location overriding constraints.')
add('Is Presence destroyed on moving into an already-Blighted land? If a cascade loops back into a land it already hit, can it destroy Presence there again, and does existing Blight quantity multiply cascading?', 'Entering existing Blight does not destroy Presence. Each new Blight addition, including cascade revisits, destroys one Presence per Spirit present and can cascade onward again. Existing Blight quantity does not multiply the single outgoing cascade.', ['CORE p.15','FAQ Core: .3y28auk; .7w4g8nw'], 'Existing Blight versus adding and cascade revisits.')
add('If a Healthy Blight pool empties before a cascade is complete, when do you flip/refill and do you finish the cascade? Does removing Blight restore destroyed Presence?', 'Immediately follow empty-pool instructions, flip/refill from box as directed, and continue unfinished additions/cascades; no setup +1 is added on flip. Removing Blight only returns it to active pool; does not restore destroyed Presence or flip back to Healthy.', ['CORE pp.15,18','FAQ Core: .7w4g8r7; one-more-blight-errata'], 'Pool transition during unresolved cascade; no Presence recovery from removal.')
add('If a Ravage in one land cascades Blight across the board boundary, is that cascade a separate independent action for victory/defeat checks? May players choose another land’s Ravage first to win before a later losing Ravage?', 'Cascade remains part of original single-land Ravage action tree, not a separate outcome-check boundary. Players choose land order and may win at the end of one complete Ravage tree before another land Ravages and could cause loss.', ['CORE p.9','FAQ Core: .7w4geg1; .bu6oc8v; .9v5kfq7'], 'Cascade action identity and consequential between-land outcome ordering.')
add('A Stage III Ravage lists Sands and Jungles. Before it starts one matching land is empty. A triggered effect during another Ravage moves an Invader into that empty land and more Invaders into a land already due to Ravage. Which lands Ravage and which Invaders participate?', 'Determine matching eligible lands before resolving the card: initially empty land does not gain a Ravage from this card. In a land already queued to Ravage, new Invaders participate when it resolves. Players may choose any order across both terrains.', ['FAQ Core: pieces-added-or-moved-by-ravages-do-not-cause-more-ravages; .9v5kaam'], 'Eligibility list frozen but participating pieces current.')
add('What does the Coastal Lands Invader card affect when Exploring, Building and Ravaging, and do its Build/Ravage effects bypass usual requirements?', 'All Coastal lands across boards; later Build/Ravage likewise in Coastal lands. Normal restrictions remain: Build/Ravage only eligible lands with Invaders, Explore requires sources (Ocean provides coast access).', ['CORE pp.9-10,13','FAQ Core: .7w4g9as'], 'Coastal card propagating through actions, not a terrain or exception.')
add('If a Year of Perfect Stillness or Paralyzing Fright skips actions in a land containing a Town, does it stop an adjacent matching land Exploring from that Town?', 'No. Skipping actions in source land does not remove its Town/City or prevent neighboring Explore checking that source; the Explore action happens in the destination land.', ['FAQ Core: .7w4g8p8'], 'Skip-action locality versus source existence.')
add('After Invader cards advance, can Slow Powers remove a newly added Explorer to prevent a future Build, or has it already Built? When does Fear from a Slow Power normally resolve?', 'Yes: just-Explored card is now in Build for next turn, so removing that Explorer before then can prevent its Build. It did not Build during that Explore. Fear cards earned in Slow wait until next Invader Phase’s Fear step.', ['CORE pp.9-10,12,21'], 'Slow-phase board forecast, advance timing and Fear scheduling.')
add('Do each-player Fear choices need different lands or pieces, and may a player use another Spirit’s Sacred Site for a generic Fear-card condition? What if the card explicitly counts each Spirit’s own Sacred Sites?', 'Different choices only when the card requires them; a piece may move multiple times across successive player choices if legal. Generic Presence/site conditions accept any Spirit’s; explicitly individual own-site counts use each Spirit’s sites separately.', ['CORE p.9','FAQ Core: fear-cards-checking-for-presence; .9v5ka9n'], 'Sequential per-player choices and generic versus individual site checks.')
add('An effect removes two Invaders in a land with two Cities. Must Explorers be removed first, and if a card instead allows removing a number of Health worth, does existing Damage reduce that Health?', 'May remove both Cities; Invader includes all three types and no Explorer-first rule applies. Health allowance uses current Health modifiers but marked Damage does not reduce Health.', ['CORE pp.15,18,30','FAQ Core: .9v5kaai'], 'Generic Invader choice versus Health-value removal.')
add('If a condition says Dahan outnumber Towns/Cities, can it hold with zero buildings? What if both sides are zero?', 'Yes with at least one Dahan and zero buildings. Zero versus zero is not outnumbering.', ['CORE p.31','FAQ Core: .bu6od0k'], 'Zero-opposition outnumber condition.')
add('How does one-Spirit solo change Another Spirit targeting and conditional other-Spirit bonuses? Does one human playing two Spirits get that same self-targeting exception or use one-person setup scaling?', 'Single Spirit may target itself with Another Spirit, but cannot get bonuses conditional on actually targeting another. One human playing two Spirits fills two player roles, scales by two and does not get the single-Spirit targeting exception.', ['CORE p.22','FAQ Setup: Can-one-person-play-more-than-one-Spirit'], 'True solo versus multi-handed roles and conditional bonuses.')
add('When players disagree about a Power’s choices, a Blight cascade destination, or a decision outside any land, who ultimately decides?', 'Power user chooses Power decisions. Otherwise seek consensus; if impossible, land decisions belong to Spirit starting on that board, and non-land decisions to game owner/organizer.', ['CORE p.8 sidebar'], 'Decision authority fallback.')
add('Do low-complexity Spirits always have to use Power Progression? If used, how are gains and Major Forgetting handled, and how does the introductory no-Blight-Card game end from Blight?', 'Progression is optional teaching aid. Take next listed card into hand instead of draw-four/keep-one; gaining a Major still requires Forgetting. No-card initial pool is 5 per Spirit +1 total and emptying it loses, without flip or ongoing Blighted effect.', ['CORE pp.3,6,18','FAQ Core: .9v5kavp','FAQ Setup: one-more-blight-errata'], 'Teaching alternatives and no-card outcome branch.')
add('For Dahan Enheartened at Terror II or III, may each player choose a land already containing Dahan and Gather zero? Must chosen lands differ and is Damage per Invader?', 'Yes, each player chooses a different land and may Gather up to two (including zero). Then II deals one total Damage if Dahan present; III deals total Damage equal to Dahan present, not that amount to each Invader.', ['FAQ Core: .7w4g8rq; .7w4g8ra'], 'Fear-card update, zero Gather and total-versus-per-piece Damage.')
add('Under Overseas Trade Seems Safer II, a Coastal land would build a City and a second would build a Town. What happens in each? Does Trade Suffers III allow an Inland City to be downgraded?', 'The Coastal City Build is entirely skipped; no Town substitute. The Town Build proceeds normally. Trade Suffers III only downgrades in Coastal lands, including when choosing a City.', ['FAQ Core: .7w4g8qr; .bu6ocpc'], 'Specific Fear skip outcome and modifier scope.')
add('A single-land Defend-per-Dahan Power resolves, then some Dahan leave. Compare that with Dahan on their Guard and with Encompassing Ward when Presence moves.', 'Single-land Power normally fixes its Defend from contents at use. Island-wide Dahan on their Guard checks current Dahan when damage occurs. Encompassing Ward follows current Presence of target Spirit, so lands gaining/losing that Presence gain/lose its Defend.', ['FAQ Core: do-island-wide-effects-check-land-contents-at-resolution; .7w4ganu'], 'Snapshot versus dynamic class-of-lands effects.')
add('When Crops Wither and Fade offers an or choice, is its 2 Fear optional? If Veil the Night’s Hunt has three Dahan but two Invaders, can the third point be added to an already-hit Invader?', 'Always gain the two Fear; or only separates City/Town replacement clauses. Veil deals one Damage each to the two different Invaders and wastes the third; cannot concentrate it.', ['FAQ Core: .9v5kavn; .7w4g8qc'], 'Printed clause groupings and forced distinct Damage targets.')
add('What is Song of Sanctity’s speed if its cost-circle color is missing? What does the missing symbol on Dissolve the Bonds of Kinship’s third line require, and is its Invader-on-Invader Damage simultaneous?', 'Song of Sanctity is Slow. Dissolve line three Pushes all Explorers from target land. Its Invader-on-Invader Damage is simultaneous, so pieces can destroy each other.', ['FAQ Core: .7w4g9dg; .9v5kc31; .7w4ganc'], 'Specific base-card misprints and simultaneous reciprocal Damage.')
add('Does Poisoned Land’s threshold count Blight that the Power itself just added? How is Tsunami’s extra Fear applied, and does an unqualified +4 Damage threshold add 4 to every piece hit earlier?', 'Poisoned Land counts its own earlier added Blight. Tsunami threshold generates extra Fear for each other affected Coastal land. Unqualified +4 Damage is four total Damage when that threshold resolves, not four per earlier piece.', ['FAQ Core: .7w4g8q3; .7w4g8pc; .7w4g8p0'], 'Instruction-order counts, other-land Fear and additive Damage interpretation.')
add('Can Wrap in Wings of Sunlight grant Defend if it moves zero Dahan? Can it count as movement when Dahan are moved to their current land if otherwise permitted? Can Blazing Renewal do threshold Damage with no destroyed Presence to add?', 'Zero Move grants no Defend because there is no moved-to land. Moving Dahan to their own land counts as Move when not otherwise restricted. Blazing Renewal cannot deal threshold Damage without restoring destroyed Presence; that land is the placement land.', ['FAQ Core: .9v5kfqd; .9v5kfr0; .bu6oc8n'], 'Dependent destinations fail when nothing moves/is placed.')
add('The Trees and Stones Speak of War is used with five Dahan and its threshold Pushes two to different adjacent lands. How much Defend stays and reaches each destination? Does a later unrelated Dahan move carry it further?', 'Defend 6 stays in original land and Defend 2 reaches each destination (2 per Dahan Pushed by this Power), independent of other Dahan there. Later unrelated movement does not carry Defend. Additional Defend boosts in original land stay there.', ['FAQ Core: .bu6ocxq'], 'Explicit mobile Defend exception and non-transfer of separate boosts.')
add('Does Infinite Vitality’s threshold save Dahan from Remove or Replace? Does its Blight protection prohibit choosing the land as a cascade destination?', 'It protects from Damage/Destroy, not Remove/Replace. Protected land remains a legal Blight/cascade choice; protection changes what happens, not whether it may be selected.', ['FAQ Core: .bu6ocxx; .7w4g8q2'], 'Protection categories versus choice legality.')
add('Two Spirits with one Presence each in the same land use Entwined Power. For what purposes may they treat it as a Sacred Site? Does this allow counting the other’s Presence in a Power’s text, and does River’s Wetland rule transfer to the other Spirit?', 'May treat combined Presence as a site only while targeting Powers. Not a real site for Fear or other effects, and no shared Presence for Power text/your-land effects. River’s Wetland special site rule remains River’s own, not the other Spirit’s.', ['FAQ Core: .3y28auq; .3y28aeu'], 'Targeting-only Presence sharing versus real sites/text effects.')
add('In solo, what does Entwined Power grant from its normal gain wording and its Energy threshold? Can gifting another Spirit a Unique with a defined special effect such as Drown still use that definition?', 'It can gain two Power Cards and with threshold gain 6 Energy; separate Major gains each need Forgetting. Defined special effects such as Drown remain usable from the gifted card and go to Ocean’s panel as defined; skip instructions requiring an unavailable personal track.', ['FAQ Core: .7w4g9jw; .7w4gee7; .7w4g8p9'], 'Solo dual-recipient wording and transferred effect definitions.')
add('Can Mantle of Dread choose one of target Spirit’s lands with only an Explorer even when another land has Explorer and Town? Can Tidal Boon Push Dahan from a land without a Town, and does its if-Dahan-are-pushed clause apply to later unrelated Pushes?', 'Yes to both land choices: target Spirit chooses one of its lands and does as much as possible there. Tidal Boon’s clause applies only to its own Push, not later unrelated Pushes.', ['FAQ Core: .7w4gdab; .9v5kfhb; .bu6oebp'], 'Spirit-chosen effect land versus maximizing all instructions.')
add('Where is Fear from a Spirit-targeting Mantle of Dread generated for Dread Apparitions? Compare Fear from Harbingers of the Lightning.', 'Mantle’s Spirit-targeting Fear has no specific land unless text names one, so does not supply a land for Dread Apparitions. Harbingers’ Fear is generated in its target land.', ['FAQ Core: where-do-spirit-targeting-powers-add-their-fear; .7w4gefg'], 'Spirit-targeting Fear without location versus land-targeted Fear.')
add('When does Lightning use Swiftness of Lightning, how many Powers can it make Fast, do Innates count, and what if Air is gained or lost during the turn?', 'Use during Fast; one Power per current Air Element, including Innates. Recheck current allowance each use; prior uses still count, so gaining/loss changes remaining uses rather than resetting uses or locking a prior peak.', ['FAQ Core: .9v5kehe; when-does-swiftness-of-lightning-happen; if-a-special-rule-cares-about-elements-when-does-it-check-your-element-total'], 'Element-linked limited-use special rule and timing.')
add('River has one disk in Wetland, making it a Sacred Site via River’s Domain. Does this count as two Presence for effects? When moving or affecting a Sacred Site, can River use one or two actual Presence?', 'No imaginary second disk; count actual disks. For an effect moving/affecting a Sacred Site, River may choose one or two actual Presence as applicable/available.', ['FAQ Core: .9v5kfd7; .7w4gebd'], 'Counts-as site versus actual disk amount.')
add('Shadows pays Shadows of the Dahan to use a Sacred-Site-origin Power on a Dahan land far away. What requirements remain, when is the surcharge paid, and must it be paid again for a Repeat?', 'Need an actual Sacred Site origin and all other nonnumeric source/target restrictions. Pay one Energy when using the Power, not card play. Numeric range-ignore modification carries to Repeat without another surcharge; explicit Repeat location overrides normal targeting.', ['FAQ Core: .7w4g8nq; .7w4g8pt; .7w4g8r6'], 'Paid range ignore preserves sources and persists into repeat.')
add('For Shadows’ Darkness Swallows the Unwary, may a player use only the second level to destroy Explorers while declining a possible first-level Gather when both levels use the same required Elements?', 'No. Choosing fewer Elements applies consistently to whole Power; if Elements meet the second and thereby first, perform first-level Gather if possible before destroying. Cannot choose individual threshold instructions to omit.', ['FAQ Core: .bu6od0c'], 'Threshold consistency enforced by identical prerequisite structure.')
add('Is Rampant Green’s Choke the Land with Green mandatory in a printing missing may? Does Steady Regeneration check local land Blight or the Blight Card? Can Growth’s mandatory placement await the Power gained by another selected option?', 'Choke is optional. Steady Regeneration checks Healthy/Blighted state of Blight Card, not destination land’s Blight. May order Growth instructions so the gained Power informs the mandatory placement; explicit regeneration can use destroyed Presence.', ['FAQ Core: .9v5kc2v; .7w4g8r1; .bu6oegz; .7w4g8nv'], 'Green erratum and Healthy-state referent/order.')
add('Two Dahan Move (not Gather or Push) from one land to another. How many of Thunderspeaker’s Presence may accompany them? If they move into an Ocean made legal by Ocean’s rule, may Presence accompany them there?', 'Up to one Presence per moved Dahan, so two, with them. Generic Move qualifies as well as Gather/Push. Presence may accompany them into a legally targeted Ocean via the Power/Ocean-rule interaction.', ['FAQ Core: .bu6oc6l; .bu6oc73; .9v5kc4i'], 'Per-Dahan accompaniment across generic movement and legal Ocean exception.')
add('A Ravage kills a Dahan but adds no Blight because a Power prevents it. Does Sworn to Victory still destroy Thunderspeaker Presence, and before or after cascades and counterattack?', 'Yes; for each Dahan destroyed by that Ravage, destroy one of Thunderspeaker’s Presence within Range 1 after the entire single-land Ravage, including any Blight/cascades/Presence loss and counterattack. Blight is not a prerequisite.', ['FAQ Core: .bu6ofsi; what-items-are-triggered-actions'], 'Triggered Thunderspeaker loss independent of Blight and after full Ravage.')
add('On a board with Ocean’s Presence only in a Coastal land, can a Power Push Invaders into that board’s Ocean to Drown? Must Ocean have Presence in the Ocean itself, and can Fear Cards or Invader actions ordinarily use it as a land?', 'Yes, any of Ocean’s Presence on board activates Ocean In Play; no Ocean disk required. Ocean is Coastal Wetland for Powers and Blight, not normal Fear/Invader actions. Humans moved there are Drowned after originating movement action.', ['FAQ Core: .7w4g8qy; .7w4g8rn; .9v5kc4i'], 'Ocean activation and action-category restriction.')
add('Can Blight cascade into an Ocean on a board with Ocean’s Presence? Can normal Growth Add Presence to that Ocean as if a Coastal Wetland, can it measure from existing Presence there, and how can Ocean put Presence Inland in the base game?', 'Cascade into that Ocean is legal. Normal Growth cannot treat it as Coastal Wetland to add there, but may measure from existing Presence in Ocean. Indomitable Claim explicitly ignores land-type restrictions and can place Ocean Presence Inland; ordinary adding Powers do not bypass its restriction.', ['FAQ Core: .bu6odcf; .9v5kf36; .7w4gef8; .9v5ka9o'], 'Ocean Blight versus Growth and legal source versus destination.')
add('When Ocean Drowns a Town and a City, when is Fear earned and where do pieces go? In two-Spirit play how much Energy value is a drowned City worth, can change be made, and do Dahan yield Energy?', 'Fear earned immediately on destruction: 1 for Town and 2 for City. Drowned Invaders go on Ocean panel for later trade. Trade X printed Health for 1 Energy, X=Spirits, so in two-Spirit game City gives 1 Energy plus 1 Health change. Ignore Health modifiers; Dahan drown with no Energy benefit.', ['FAQ Core: .9v5kbka; .7w4g8pb; .9v5ka9g; .7w4g8r4'], 'Drowning Fear now versus later Energy conversion and printed Health.')
add('Does every watery destruction count as Drowning? If Ocean’s last Presence on a board is lost mid-action, when does Ocean In Play expire and what happens to other Spirits’ Presence and surviving humans left there?', 'Only explicit Drown or Ocean’s triggered destruction of moved-in humans is Drowning, not thematic ordinary destruction. Ocean In Play persists through current action tree, then ends. Nonhuman pieces remain physically but out of play until Ocean returns. Humans must be in legal lands: failed Drown attempts Push to non-Ocean land during that action; any still-illegal humans clean up to nearest legal land after all triggers.', ['FAQ Core: .7w4g8qy; .9v5kfqb; .9v5kfqs; .7w4gdtl; What-happens-to-items-in-the-ocean-if-OHG-has-no-presence-on-the-board'], 'Drown identity and expiry/illegal-state handling.')
add('If a human piece remains illegally placed after an action tree, how is it cleaned up? Is that a move, destroy, remove or action, and what if no legal land exists?', 'Put it in nearest legal land, using judgment/physical distance for ambiguity. Cleanup is none of move/destroy/remove/action and triggers nothing; if no legal land exists, return it to supply still as cleanup. Do before outcome check after tree.', ['FAQ Core: .7w4gdtl'], 'Illegal-state correction timing and non-action identity.')
add('Bringer uses a 2-Damage Power and then a separate 1-Damage Power on an undamaged City. What happens? What if 2 then 1 Damage are instructions within a single Power, and may a Repeat pretend-destroy the same piece again?', 'Separate Powers do not combine hypothetical Damage and each does nothing to undamaged City. Single Power’s instructions combine to would-destroy City and earn 5 Fear, leaving City actually unchanged. Repeat is separate action and can pretend-destroy same piece again if its own Damage suffices; cannot combine its hypothetical Damage with original.', ['FAQ Core: .7w4g7yx; .7w4g8pj'], 'Bringer single-action hypothetical damage versus separate/repeat uses.')
add('A City has 2 real Damage from another Spirit. Bringer then uses a 1-Damage Power twice via a Repeat. How much Fear does each use earn, does the City die, and is its real Damage erased?', 'Each hypothetical destruction earns 5 Fear, 10 total. City survives with its original 2 real Damage; Bringer neither marks new Damage nor clears real Damage. Repeat can affect same City again.', ['FAQ Core: .7w4g7yu; .9v5kfh3; .7w4g8pj'], 'Bringer leverages real damage and does not heal or consume it.')
add('For Bringer’s would-be destruction, what Fear and Push happens for Explorer, Town and City? Does Mists of Oblivion’s bonus for buildings actually destroyed or Vengeance of the Dead trigger from it?', 'Would-destroy Explorer: zero Fear and Push; Town: 2 Fear and Push; City: 5 Fear, no Push. No real destruction, so no Mists actual-destruction bonus or Vengeance trigger from pretend deaths.', ['FAQ Core: .7w4g7yx; .9v5katc'], 'Bringer piece-type outcomes and actual-destruction conditions.')
add('Can Bringer deal real Damage by a Power saying Dahan or another Spirit deals it? Contrast Fear Cards, counterattacks after its Defend, removing/replacing Invaders, and adding Blight.', 'Its Power’s explicit Damage/Destroy remains hypothetical even if wording names another actor. Fear Cards and Ravage counterattacks are separate and deal real Damage. Bringer can Remove/Replace and add real Blight; added Blight destroys Presence normally.', ['FAQ Core: .7w4g9jv; .9v5ka92; .9v5kf34; .bu6oc6g'], 'Source attribution versus independent action exceptions.')
add('Can Bringer cause real destruction by reducing a damaged piece’s Health or replacing it with a lower-Health type? If Bringer pretend-destroys a Town and Pushes it into Ocean, who Drowns it and what is total Fear?', 'Yes, its Power need not explicitly Damage/Destroy; core Health rules destroy when retained Damage meets new Health. Ocean’s separate rule Drowns Pushed Town, producing 1 actual Fear in addition to Bringer’s 2, total 3.', ['FAQ Core: can-bringer-destroy-things-indirectly; .7w4g8pf'], 'Indirect Health destruction versus Bringer modifier and independent Ocean trigger.')
add('Can Spirits May Yet Dream flip a Fear Card already earned, on top of the deck or deeper in the deck?', 'Yes, its first effect can flip any Fear Card in those locations.', ['FAQ Core: .7w4g8rd'], 'Bringer information exception to normally hidden earned/deck Fear.')
add('In Call on Midnight’s Dreams, which card is this Power for its Forget conditional? Must Bringer Forget a second card beyond the ordinary Major gain requirement to activate it, and can the forgotten original later be Repeated with Powerstorm?', 'This Power is Call on Midnight’s Dreams. Forgetting that card for ordinary Major requirement also satisfies conditional, so no second Forget. Forgotten original leaves play and cannot later be Repeated via ordinary Powerstorm once-this-turn permission.', ['FAQ Core: .9v5kc3z; .7w4gani; .9v5ka8w'], 'Specific self-Forget conditional versus distinct Forget costs and unavailable repeat.')
add('When does Vengeance of the Dead trigger if one Power destroys several buildings through multiple instructions? Can its own triggered Damage trigger itself again, and how do two separately repeated Vengeance effects interact?', 'Trigger after the entire Power/action, using total qualifying pieces destroyed, not after each instruction. Cannot trigger itself even indirectly. Two separately set-up effects can trigger each other, but an effect cannot recur within its own chain, so no infinite loop.', ['FAQ Core: .bu6oc8x; .7w4gdth; .7w4gdtj'], 'Triggered action completion and indirect recursion prohibition.')
D=B/'expanded-v1';D.mkdir(exist_ok=True)
q={**sq,'benchmark_version':'expanded-v1','questions':qs};k={**sk,'benchmark_version':'expanded-v1','answers':keys}
for name,v in [('questions.json',q),('answer-key.json',k),('novelty.json',novelty)]:
 p=D/name
 if p.exists():raise RuntimeError(f'Refuse overwrite {p}')
 p.write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n')
(D/'question-bank.md').write_text('# Spirit Island expanded bank v1\n\nOriginal 20 entries preserved. Added questions cover source-defined rules, outcome branches and consequential interactions.\n\n'+'\n\n'.join(f"## {x['id']}\n\n{x['question']}\n\n**Expected:** {y['answer']}\n\n**Sources:** {'; '.join(y['source_refs'])}" for x,y in zip(qs,keys))+'\n')
(D/'input-manifest.json').write_text(json.dumps({'question_count':len(qs),'original_entries_preserved':qs[:20]==sq['questions'] and keys[:20]==sk['answers'],'sha256':{str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in [D/'questions.json',D/'answer-key.json',B/'seed-v1/questions.json',B/'seed-v1/answer-key.json']},'source_manifest':'../source-manifest.json','source_first_seed':True,'expansion_evaluator_saw_summary':True},indent=2)+'\n')
print('Frozen expanded-v1',len(qs))
